js:
var raw = (typeof getResCode === 'function') ? getResCode() : ((typeof result !== 'undefined' && result) ? result : (typeof input !== 'undefined' ? input : ''));
var d = [];
if (raw) {
  var j = JSON.parse(raw);
  var l = (j.data && (j.data.list || j.data.content || j.data)) || [];
  if (!l.length && j.data) { for (var k in j.data) { if (Object.prototype.toString.call(j.data[k]) === '[object Array]') { l = j.data[k]; break; } } }
  for (var i = 0; i < l.length; i++) {
    var it = l[i];
    d.push({
      title: it.name || it.title || it.vod_name || '',
      img: (it.picture || it.cover || it.pic || '') + '@Referer=https://example.com',
      desc: (it.cName || it.remarks || it.year || ''),
      url: 'https://example.com/play?id=' + (it.id || it.vod_id || ''),
      col_type: 'movie_3'
    });
  }
}
setResult(d);

