detail_find_rule:
js:
var d = [];
var html = (typeof getResCode === 'function') ? getResCode() : ((typeof result !== 'undefined' && result) ? result : '');
/* 顶部 pic_1 卡：海报 + 剧名 + 简介 */
var name = '';
var hm = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/);
if (hm) { name = hm[1].replace(/<[^>]+>/g, '').trim(); }
var poster = '';
var pm = html.match(/<img[^>]*src="([^"]+)"/);
if (pm) { poster = pm[1]; }
var intro = '';
var im = html.match(/TODO_简介正则/);
if (im) { intro = im[1].replace(/<[^>]+>/g, '').trim(); }
d.push({ title: name || '详情', desc: intro, pic_url: poster, col_type: 'pic_1' });
/* 线路 + 选集（playList 2D 数组：[线路][集数]） */
/* TODO: 提取 playList，每个线路一行 text_1，每集一行 text_2，url 拼 m3u8/播放直链 */
d.push({ title: '线路1（共N集）', col_type: 'text_1' });
d.push({ title: '第1集', url: 'https://example.com/play/1.m3u8#isVideo=true#', col_type: 'text_2' });
setResult(d);
